INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "史俨李承嗣以万骑驰援郓州", "start_year": 895, "end_year": 895, "time_original": "895年五月诏讨董以前；确日未载", "dynasty": "唐", "description": "河东派史俨、李承嗣领万骑驰入郓州。", "phases": [], "location_name": "郓州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "079e6385-8a17-5182-ba51-412fc845bc02"}, {"title": "朱友恭退回汴州", "start_year": 895, "end_year": 895, "time_original": "895年河东骑入郓后；确日未载", "dynasty": "唐", "description": "朱友恭退回汴州。", "phases": [], "location_name": "汴州、郓州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "1eb53e3b-e8d0-5e0a-9eda-08dadd42f401"}, {"title": "朝廷削董昌官爵，委钱镠讨之", "start_year": 895, "end_year": 895, "time_original": "895年五月；具体日未载", "dynasty": "唐", "description": "朝廷下诏剥夺董昌官爵，委钱镠讨伐。", "phases": [], "location_name": "朝廷、浙东", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "5d140bdc-8f0b-5013-b47e-4ad17d619ce5"}, {"title": "王行瑜因未获尚书令怨朝廷", "start_year": null, "end_year": null, "time_original": "初；五月入京以前，确年待考", "dynasty": "唐", "description": "王行瑜曾求尚书令未得，因此怨朝廷。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "774f5258-ed1b-52c9-882e-d8392e910390"}, {"title": "韩建王行瑜求取禁军两镇，宦官拒之", "start_year": null, "end_year": null, "time_original": "五月入京以前；确年待考", "dynasty": "唐", "description": "畿内八镇兵隶左右军，韩建求取近华州的郃阳镇，王行瑜求取近邠州的良原镇。宦官以其为天子禁军，拒绝。", "phases": [], "location_name": "郃阳、良原、华州、邠州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "a9c82313-7b14-50ba-b5e7-6e81c45417b4"}, {"title": "三帅为王珙请河中不得而耻", "start_year": 895, "end_year": 895, "time_original": "895年五月以前河中争位期间；确日未载", "dynasty": "唐", "description": "王行瑜、韩建、李茂贞为王珙请求河中未得，感到耻辱。", "phases": [], "location_name": "河中、朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "cedcaff5-59f0-5769-a656-6c9d594910ca"}, {"title": "王珙遣人劝三帅讨王珂", "start_year": 895, "end_year": 895, "time_original": "895年五月入京以前；确日未载", "dynasty": "唐", "description": "王珙遣人向三帅声称王珂不受代且与河东联姻，必对三帅不利，请求讨伐王珂。", "phases": [], "location_name": "河中", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "9655987a-f46c-5f2a-9ae8-2c100f1be86e"}, {"title": "王行约攻河中，王珂求救李克用", "start_year": 895, "end_year": 895, "time_original": "895年五月三帅入京以前；确日未载", "dynasty": "唐", "description": "王行瑜命弟、匡国节度使王行约攻河中，王珂向李克用求救。", "phases": [], "location_name": "河中", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "6b8b9cb1-9e20-5db0-a140-2c167ed7e744"}, {"title": "三帅各领精兵数千入京，坊市民窜匿", "start_year": 895, "end_year": 895, "time_original": "895年五月甲子", "dynasty": "唐", "description": "王行瑜、李茂贞、韩建各领精兵数千入朝，甲子抵京师，坊市居民窜匿。", "phases": [], "location_name": "京师、坊市", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "d5880a5c-da6d-5a8f-8663-828f11812222"}, {"title": "唐昭宗临安福门亲诘三帅称兵入京", "start_year": 895, "end_year": 895, "time_original": "895年五月甲子", "dynasty": "唐", "description": "唐昭宗御安福门，三帅盛陈甲兵、拜伏舞蹈。皇帝责其未奏请候报而称兵入京；王行瑜、李茂贞流汗失语，韩建略述原因。", "phases": [], "location_name": "安福门", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "a05771cd-fc3a-537b-a4ef-fc990673bd18"}, {"title": "三帅宴中请诛韦昭度李磎，皇帝未许", "start_year": 895, "end_year": 895, "time_original": "895年五月甲子", "dynasty": "唐", "description": "皇帝宴三帅，三帅称南北司结党乱政、韦昭度讨西川失策、李磎不合众心，请诛二人，皇帝尚未准许。", "phases": [], "location_name": "京师、宴席", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e15d936f-479f-53c0-8603-bd3712acf0ec"}, {"title": "王行瑜等杀韦昭度李磎康尚弼", "start_year": 895, "end_year": 895, "time_original": "895年五月甲子", "dynasty": "唐", "description": "王行瑜等当日杀韦昭度、李磎于都亭驿，又杀枢密使康尚弼及宦官数人。", "phases": [], "location_name": "都亭驿、京师", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "363153af-ee42-58ad-8361-3ea689ef4b94"}, {"title": "三帅请王珙领河中并徙行约王珂，皇帝许", "start_year": 895, "end_year": 895, "time_original": "895年五月甲子", "dynasty": "唐", "description": "三帅称王珂、王珙嫡庶不分，请王珙领河中、王行约改陕州、王珂改同州，皇帝均许。", "phases": [], "location_name": "河中、陕州、同州、朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "7cf722e4-c041-5878-b442-55bc2464d5b2"}, {"title": "三帅谋废唐昭宗立吉王李保", "start_year": null, "end_year": null, "time_original": "始；895年五月入京前后，谋议确日未载", "dynasty": "唐", "description": "三帅曾谋废唐昭宗，立吉王李保。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "86aed904-2d95-5e75-8be9-a4ae26fdd13a"}, {"title": "闻李克用起兵，行瑜茂贞留兵后辞还镇", "start_year": 895, "end_year": 895, "time_original": "895年五月甲子入京事后；确日未另载", "dynasty": "唐", "description": "三帅闻李克用已起兵于河东，王行瑜、李茂贞各留二千兵宿卫京师，与韩建均辞还镇。", "phases": [], "location_name": "京师、河东", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "6b9106a5-8795-5383-9f80-c416e8d41158"}, {"title": "杨堪贬雅州刺史", "start_year": 895, "end_year": 895, "time_original": "895年五月三帅入京事后；确日未载", "dynasty": "唐", "description": "户部尚书杨堪被贬为雅州刺史。", "phases": [], "location_name": "雅州、朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "66227c5a-d2b5-57b0-b61f-d8823afd0f45"}, {"title": "河东进奏官薛志勤扬言刘崇望更合李克用", "start_year": null, "end_year": null, "time_original": "初；崔胤除河中帅时，确年待考", "dynasty": "唐", "description": "崔胤被任河中节度使时，河东进奏官薛志勤称，与其以崔胤代王珂，不如与李克用更厚的光德刘公。光德刘公为太常卿刘崇望。", "phases": [], "location_name": "朝廷、河中", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "55a7c789-8723-59a5-8e7a-8b49c012be27"}, {"title": "三帅闻薛言，贬刘崇望昭州司马", "start_year": 895, "end_year": 895, "time_original": "895年五月三帅入京时；确日未另载", "dynasty": "唐", "description": "三帅入朝听到薛志勤之言，将刘崇望贬为昭州司马。", "phases": [], "location_name": "昭州、京师", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "fd1a26af-6ad6-55fd-8a33-204afc950abc"}, {"title": "李克用遣十三辈使发北部兵，约次月入关", "start_year": 895, "end_year": 895, "time_original": "895年五月闻犯阙即日；预期来月", "dynasty": "唐", "description": "李克用闻三镇兵犯阙，当日遣使十三辈征发北部兵，约定次月渡河入关。", "phases": [], "location_name": "河东、北部、关中", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "414198e5-239b-5caa-8fc0-087da24b6824"}, {"title": "钱镠授浙东招讨使", "start_year": 895, "end_year": 895, "time_original": "895年六月庚寅", "dynasty": "唐", "description": "朝廷以钱镠为浙东招讨使。", "phases": [], "location_name": "浙东、朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "aa54df5c-d77e-52e7-868b-83d4055874b6"}, {"title": "钱镠复发兵击董昌", "start_year": 895, "end_year": 895, "time_original": "895年六月授招讨使条；确日未另载", "dynasty": "唐", "description": "钱镠再次出兵攻击董昌。", "phases": [], "location_name": "浙东", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "001770a8-7b51-5211-aded-f8a00ba44461"}]'::jsonb)
